@import "tailwindcss";

:root {
  --bg: #f3f5f8;
  --bg-elevated: #ffffff;
  --ink: #0c1222;
  --muted: #5b6678;
  --accent: #0f766e;
  --accent-soft: rgba(15, 118, 110, 0.12);
  --line: rgba(12, 18, 34, 0.1);
  --hero-glow-a: rgba(15, 118, 110, 0.16);
  --hero-glow-b: rgba(37, 99, 235, 0.1);
  --shadow-soft: 0 18px 50px rgba(12, 18, 34, 0.06);
  --radius: 12px;
}

.dark {
  --bg: #0a0e14;
  --bg-elevated: #121820;
  --ink: #e8edf5;
  --muted: #9aa6b8;
  --accent: #2dd4bf;
  --accent-soft: rgba(45, 212, 191, 0.14);
  --line: rgba(232, 237, 245, 0.1);
  --hero-glow-a: rgba(45, 212, 191, 0.12);
  --hero-glow-b: rgba(96, 165, 250, 0.08);
  --shadow-soft: 0 18px 50px rgba(0, 0, 0, 0.35);
}

@theme inline {
  --font-sans: var(--font-body);
  --font-display: var(--font-display);
  --font-mono: var(--font-mono);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  min-height: 100%;
  background: var(--bg);
  color: var(--ink);
  font-family: var(--font-body), system-ui, sans-serif;
  font-size: 1.05rem;
  line-height: 1.65;
  text-rendering: optimizeLegibility;
}

a {
  color: inherit;
  text-decoration: none;
}

::selection {
  background: var(--accent-soft);
  color: var(--ink);
}

.page {
  position: relative;
  overflow-x: clip;
}

.theme-dock {
  position: fixed;
  top: 1rem;
  right: 1rem;
  z-index: 40;
}

.theme-toggle {
  width: 2.4rem;
  height: 2.4rem;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: color-mix(in srgb, var(--bg-elevated) 88%, transparent);
  backdrop-filter: blur(10px);
  color: var(--ink);
  display: grid;
  place-items: center;
  cursor: pointer;
  transition: border-color 0.2s ease, transform 0.2s ease;
}

.theme-toggle:hover {
  border-color: color-mix(in srgb, var(--accent) 45%, var(--line));
  transform: translateY(-1px);
}

.theme-toggle__icon {
  width: 1.05rem;
  height: 1.05rem;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  min-height: 2.75rem;
  padding: 0.7rem 1.15rem;
  border-radius: 0.65rem;
  font-size: 0.95rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  border: 1px solid transparent;
  transition: transform 0.2s ease, background 0.2s ease, border-color 0.2s ease,
    color 0.2s ease;
}

.btn:hover {
  transform: translateY(-1px);
}

.btn--sm {
  min-height: 2.35rem;
  padding: 0.45rem 0.9rem;
  font-size: 0.875rem;
}

.btn--primary {
  background: var(--ink);
  color: var(--bg);
}

.dark .btn--primary {
  background: var(--accent);
  color: #041210;
}

.btn--secondary {
  background: var(--accent-soft);
  color: var(--accent);
  border-color: color-mix(in srgb, var(--accent) 28%, transparent);
}

.btn--ghost {
  background: transparent;
  color: var(--ink);
  border-color: var(--line);
}

.btn--ghost:hover {
  border-color: color-mix(in srgb, var(--ink) 28%, var(--line));
}

/* Hero */
.hero {
  position: relative;
  min-height: 100svh;
  display: grid;
  align-items: center;
  padding: 3.5rem 1.25rem 4.5rem;
  isolation: isolate;
}

.hero__atmosphere {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse 70% 55% at 12% 18%, var(--hero-glow-a), transparent 60%),
    radial-gradient(ellipse 55% 45% at 88% 12%, var(--hero-glow-b), transparent 55%),
    linear-gradient(180deg, color-mix(in srgb, var(--bg) 70%, white) 0%, var(--bg) 100%);
  z-index: -2;
}

.dark .hero__atmosphere {
  background:
    radial-gradient(ellipse 70% 55% at 12% 18%, var(--hero-glow-a), transparent 60%),
    radial-gradient(ellipse 55% 45% at 88% 12%, var(--hero-glow-b), transparent 55%),
    linear-gradient(180deg, #0d131b 0%, var(--bg) 100%);
}

.hero__grid {
  position: absolute;
  inset: 0;
  z-index: -1;
  opacity: 0.35;
  background-image:
    linear-gradient(var(--line) 1px, transparent 1px),
    linear-gradient(90deg, var(--line) 1px, transparent 1px);
  background-size: 56px 56px;
  mask-image: radial-gradient(ellipse 70% 60% at 50% 35%, black 20%, transparent 75%);
}

.hero__content {
  max-width: 1120px;
  margin: 0 auto;
  width: 100%;
}

.hero__meta {
  margin: 0 0 1.1rem;
  font-family: var(--font-mono), ui-monospace, monospace;
  font-size: 0.82rem;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--accent);
}

.hero__status {
  margin: -0.45rem 0 1.25rem;
  display: inline-block;
  font-size: 0.92rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  color: var(--ink);
  border-bottom: 2px solid var(--accent);
  padding-bottom: 0.15rem;
}

.hero__name {
  margin: 0;
  max-width: 14ch;
  font-family: var(--font-display), sans-serif;
  font-size: clamp(3rem, 9vw, 6.4rem);
  line-height: 0.95;
  letter-spacing: -0.055em;
  font-weight: 700;
}

.hero__lede {
  margin: 1.5rem 0 0;
  max-width: 38rem;
  font-size: clamp(1.05rem, 2.1vw, 1.25rem);
  color: var(--muted);
  line-height: 1.7;
}

.hero__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  margin-top: 2rem;
}

.hero__links {
  list-style: none;
  display: flex;
  flex-wrap: wrap;
  gap: 1.1rem;
  margin: 2rem 0 0;
  padding: 0;
}

.hero__links a {
  font-size: 0.95rem;
  color: var(--muted);
  border-bottom: 1px solid transparent;
  transition: color 0.2s ease, border-color 0.2s ease;
}

.hero__links a:hover {
  color: var(--ink);
  border-color: var(--accent);
}

.reveal {
  animation: rise 0.8s cubic-bezier(0.22, 1, 0.36, 1) both;
}

@keyframes rise {
  from {
    opacity: 0;
    transform: translateY(18px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .reveal {
    animation: none;
  }

  html {
    scroll-behavior: auto;
  }
}

/* Sections */
.section {
  max-width: 1120px;
  margin: 0 auto;
  padding: 5rem 1.25rem;
}

.section--compact {
  padding-top: 2rem;
}

strong {
  font-weight: 700;
  color: var(--ink);
}

.section--contact {
  padding-bottom: 4rem;
