  font-size: clamp(2rem, 4vw, 2.75rem);
  letter-spacing: -0.04em;
  line-height: 1.1;
}

.section__lede {
  margin: 0.85rem 0 0;
  color: var(--muted);
  font-size: 1.05rem;
}

/* Experience timeline */
.timeline {
  display: grid;
  gap: 2rem;
}

.timeline__item {
  display: grid;
  gap: 1rem;
  padding-bottom: 2rem;
  border-bottom: 1px solid var(--line);
}

.timeline__item:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}

.timeline__period {
  margin: 0;
  font-family: var(--font-mono), ui-monospace, monospace;
  font-size: 0.85rem;
  color: var(--accent);
}

.timeline__location {
  margin: 0.35rem 0 0;
  font-size: 0.92rem;
  color: var(--muted);
}

.timeline__role {
  margin: 0;
  font-size: 1.35rem;
  letter-spacing: -0.02em;
